**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("wielokaty.txt");
    int k;
    plik >> k;
    double maxObw = -1;
    int maxIdx = -1;
    cout << fixed << setprecision(2);
    for (int w = 0; w < k; w++) {
        int n;
        plik >> n;
        vector<int> X(n), Y(n);
        for (int i = 0; i < n; i++) plik >> X[i] >> Y[i];
        double obw = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            double dx = X[j] - X[i];
            double dy = Y[j] - Y[i];
            obw += sqrt(dx * dx + dy * dy);
        }
        cout << "Wielokat " << w + 1 << " (" << n << " wierzch.): obwod = " << obw << endl;
        if (obw > maxObw) {
            maxObw = obw;
            maxIdx = w + 1;
        }
    }
    cout << "Najdluzszy obwod: wielokat " << maxIdx << ", obwod = " << maxObw << endl;
    return 0;
}
```

**Wyjasnienie**: Obwod wielokata to suma dlugosci jego bokow. Kazdy bok laczy sasiednie wierzcholki, z ostatnim bokiem zamykajacym wielokat (od ostatniego wierzcholka do pierwszego).

Weryfikacja:
- W1 (trojkat 0,0-4,0-0,3): boki sqrt(16)=4, sqrt(16+9)=5, sqrt(9)=3 -> obwod = 12.00
- W2 (prostokat 6x4): boki 6+4+6+4 = 20.00
- W3 (trojkat 0,0-6,0-0,8): boki sqrt(36)=6, sqrt(36+64)=sqrt(100)=10, sqrt(64)=8 -> obwod = 24.00
- Najdluzszy: W3, obwod = 24.00
